CREATE EXTENSION IF NOT EXISTS postgis;CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),email text UNIQUE NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE families(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE family_memberships(family_id uuid NOT NULL REFERENCES families(id) ON DELETE CASCADE,user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,role text NOT NULL CHECK(role IN('guardian','adult_member')),PRIMARY KEY(family_id,user_id));
CREATE TABLE athletes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),family_id uuid NOT NULL REFERENCES families(id) ON DELETE CASCADE,first_name text NOT NULL,last_name text NOT NULL,birth_date date,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE organizations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE seasons(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid REFERENCES organizations(id) ON DELETE CASCADE,name text NOT NULL,starts_on date,ends_on date);
CREATE TABLE teams(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid REFERENCES organizations(id) ON DELETE SET NULL,season_id uuid REFERENCES seasons(id) ON DELETE SET NULL,sport_code text NOT NULL,name text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE team_memberships(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),team_id uuid NOT NULL REFERENCES teams(id) ON DELETE CASCADE,athlete_id uuid REFERENCES athletes(id) ON DELETE CASCADE,user_id uuid REFERENCES users(id) ON DELETE CASCADE,role text NOT NULL,CHECK((athlete_id IS NOT NULL)::int+(user_id IS NOT NULL)::int=1));
CREATE TABLE venues(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,address_text text,location geography(Point,4326),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE playing_surfaces(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),venue_id uuid NOT NULL REFERENCES venues(id) ON DELETE CASCADE,name text NOT NULL,surface_type text NOT NULL);
CREATE TABLE events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),team_id uuid NOT NULL REFERENCES teams(id) ON DELETE CASCADE,event_type text NOT NULL CHECK(event_type IN('practice','game','tournament','tryout','team_event')),title text NOT NULL,starts_at timestamptz NOT NULL,ends_at timestamptz,arrival_at timestamptz,venue_id uuid REFERENCES venues(id) ON DELETE SET NULL,surface_id uuid REFERENCES playing_surfaces(id) ON DELETE SET NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE rsvps(event_id uuid NOT NULL REFERENCES events(id) ON DELETE CASCADE,athlete_id uuid NOT NULL REFERENCES athletes(id) ON DELETE CASCADE,status text NOT NULL CHECK(status IN('yes','no','maybe','unknown')),updated_by uuid REFERENCES users(id) ON DELETE SET NULL,updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(event_id,athlete_id));
CREATE TABLE check_ins(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),event_id uuid NOT NULL REFERENCES events(id) ON DELETE CASCADE,athlete_id uuid REFERENCES athletes(id) ON DELETE CASCADE,user_id uuid REFERENCES users(id) ON DELETE SET NULL,state text NOT NULL CHECK(state IN('on_the_way','arrived','leaving')),checked_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE games(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),event_id uuid UNIQUE NOT NULL REFERENCES events(id) ON DELETE CASCADE,opponent_name text,status text NOT NULL DEFAULT 'scheduled',home_score integer NOT NULL DEFAULT 0,away_score integer NOT NULL DEFAULT 0);
CREATE TABLE pitching_appearances(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),game_id uuid NOT NULL REFERENCES games(id) ON DELETE CASCADE,athlete_id uuid NOT NULL REFERENCES athletes(id) ON DELETE CASCADE,pitches integer NOT NULL DEFAULT 0,strikes integer NOT NULL DEFAULT 0,innings_pitched numeric(4,1) NOT NULL DEFAULT 0,strikeouts integer NOT NULL DEFAULT 0,walks integer NOT NULL DEFAULT 0,hits_allowed integer NOT NULL DEFAULT 0,earned_runs integer NOT NULL DEFAULT 0,UNIQUE(game_id,athlete_id));
CREATE INDEX idx_events_team_start ON events(team_id,starts_at);CREATE INDEX idx_venues_location ON venues USING gist(location);CREATE INDEX idx_checkins_event_time ON check_ins(event_id,checked_at DESC);
